head.script:
scwin.trigger1_onclick = function(e) {
    var rowCount = pivotTable1.getTotalRow();
    resultTest = "row count is " + rowCount;
    //alert("row count is " + rowCount);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step IE6,7,8은 미지원 1. 샘플파일을 실행 후 'get Row Count'버튼을 클릭한다.
    //IE6, 7 and 8 are not supported 1. Run the sample file and click the 'get Row Count' button.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "typeof WebSquare.wUnit.getObjById('wq_uuid_5') == 'object'", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_5').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 1. 알림창에 'row count is 4'값이 보여진다.(이전에는 피벗테이블의 row값을 가져오는 API가 없었음)
    //1. Notice that the 'row count is 4' value is displayed (there was no API to get the row value of the pivot table before)
    WebSquare.wUnit.addCommand("assert", "resultTest == 'row count is 4'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
